const sample = {
  "demo": true,
  "title": "Carriers tighten pickup windows",
  "url": "https://example.com/news/pickups",
  "body": "A named owner and a faster first reply still decide who gets the lane."
};
const incoming = $input.first()?.json ?? {};
const provided = Object.keys(incoming).filter((key) => incoming[key] !== undefined && incoming[key] !== null && incoming[key] !== '');
const base = provided.length ? { ...sample, ...incoming } : { ...sample };
const flag = incoming.demo;
base.demo = !(flag === false || flag === 'false' || flag === 0 || flag === '0');
return [{ json: base }];

const item = $input.first().json;
const produced = (() => {

const title = String(item.title || 'Untitled').trim();
const source = String(item.transcript || item.body || item.summary || '').replace(/\s+/g, ' ').trim();
const sentence = source.split(/(?<=\.)\s/)[0] || source.slice(0, 180);
const linkedin = sentence.slice(0, 420) + (sentence.length > 420 ? '…' : '') + '\n\nFull piece: ' + (item.url || 'link in comments');
const x = (title + ' — ' + sentence).slice(0, 240);
const shorts = source.split(/(?<=\.)\s/).slice(0, 3).map((line, index) => (index + 1) + '. ' + line.trim());
const record = {
  title,
  url: item.url || '',
  linkedin,
  x,
  carousel: shorts,
  status: 'draft',
};
return {
  summary: 'Drafted LinkedIn, X, and a 3-beat carousel from "' + title + '".',
  route: 'draft',
  record,
  slackText: 'Social drafts ready for "' + title + '".',
  actions: [
    { app: 'LinkedIn', operation: 'draft', payload: { text: linkedin } },
    { app: 'X', operation: 'draft', payload: { text: x } },
  ],
};

})();
if (!produced || typeof produced.summary !== 'string' || !produced.summary.trim()) {
  throw new Error('Apply rules must return a summary string');
}
return [{
  json: {
    ...item,
    ...produced,
    demo: item.demo !== false,
  },
}];

const item = $input.first().json;
return [{
  json: {
    demo: true,
    status: 'demo_ready',
    workflow: 'industry-news-enrichment',
    summary: item.summary,
    route: item.route ?? null,
    record: item.record ?? {},
    actions: item.actions ?? [],
    slackText: item.slackText ?? item.summary,
    notes: 'Demo mode did not call external apps. Send {"demo": false} after placeholder credentials are replaced.',
  },
}];
